def choose_move(observation):
    def clamp_step(t, s):
        if t > s:
            return 1
        if t < s:
            return -1
        return 0

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def first_pair(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return None

    def pick_best(items, sx, sy, prefer_max=False):
        best = None
        best_score = None
        for item in items or []:
            p = first_pair(item)
            if p is None:
                continue
            score = manhattan((sx, sy), p)
            if best is None or (prefer_max and score > best_score) or (not prefer_max and score < best_score):
                best = p
                best_score = score
        return best

    env = observation.get("environment_name", "resource_collection")
    self_pos = first_pair(observation.get("self_position")) or (0, 0)
    sx, sy = self_pos
    opp_pos = first_pair(observation.get("opponent_position"))
    ox, oy = opp_pos if opp_pos is not None else (sx, sy)

    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            dx = clamp_step(ox, sx)
            dy = clamp_step(oy, sy)
            return [dx, dy]
        corners = []
        if w and h:
            corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        else:
            corners = [(-1, -1), (-1, 1), (1, -1), (1, 1)]
        target = pick_best(corners, ox, oy, prefer_max=True)
        if target is None:
            return [0, 0]
        return [clamp_step(target[0], sx), clamp_step(target[1], sy)]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        target = pick_best(targets, sx, sy, prefer_max=False)
        if target is None:
            if w and h:
                target = (w // 2, h // 2)
            else:
                target = (ox, oy)
        return [clamp_step(target[0], sx), clamp_step(target[1], sy)]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = pick_best(resources, sx, sy, prefer_max=False)

    if target is None:
        if opp_pos is not None:
            if w and h:
                cx, cy = w // 2, h // 2
                if abs(sx - cx) + abs(sy - cy) < abs(sx - ox) + abs(sy - oy):
                    target = (ox, oy)
                else:
                    target = (cx, cy)
            else:
                target = (ox, oy)
        else:
            target = (sx, sy)

    return [clamp_step(target[0], sx), clamp_step(target[1], sy)]

